BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
DO $$ BEGIN
 IF current_database()<>'colourfuel' OR NOT EXISTS(SELECT 1 FROM colourfuel.schema_migration WHERE migration_id='004_live_web_catalog') THEN RAISE EXCEPTION 'Wrong database or missing live catalogue'; END IF;
END $$;

