CREATE TABLE IF NOT EXISTS colourfuel_web.product (
 product_id text PRIMARY KEY,name text NOT NULL,collection text NOT NULL,description text NOT NULL,
 recipe_id text NOT NULL REFERENCES colourfuel.recipe,accent text NOT NULL,
 illustrative_price_cents integer NOT NULL CHECK(illustrative_price_cents>0),display_order integer NOT NULL,
 stage text NOT NULL CHECK(stage='development_sample')
);
CREATE TABLE IF NOT EXISTS colourfuel_web.goal_preset (
 preset_id text PRIMARY KEY,product_id text NOT NULL REFERENCES colourfuel_web.product,
 label text NOT NULL,goal_metric text NOT NULL,recipe_id text NOT NULL REFERENCES colourfuel.recipe,
 required_original jsonb NOT NULL,weights jsonb NOT NULL,required_sources jsonb NOT NULL,
 review jsonb NOT NULL,exclusions jsonb NOT NULL
);
REVOKE ALL ON colourfuel_web.product,colourfuel_web.goal_preset FROM PUBLIC;

