DO $$ DECLARE p record; base_value numeric; changed_value numeric; BEGIN
 FOR p IN SELECT * FROM colourfuel_web.goal_preset LOOP
  SELECT sum(n.value_per_100g * (x.value::text)::numeric /100) INTO base_value
   FROM jsonb_each(p.required_original) x JOIN colourfuel.ingredient_metric_resolved n ON n.variant_id=x.key AND n.metric_id=p.goal_metric;
  SELECT sum(n.value_per_100g * (x.value::text)::numeric /100) INTO changed_value
   FROM jsonb_each(p.weights) x JOIN colourfuel.ingredient_metric_resolved n ON n.variant_id=x.key AND n.metric_id=p.goal_metric;
  IF changed_value IS NULL OR base_value IS NULL OR changed_value<=base_value THEN RAISE EXCEPTION 'Preset does not increase goal metric: %',p.preset_id; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(p.weights) x LEFT JOIN colourfuel.ingredient_metric_resolved n ON n.variant_id=x.key AND n.metric_id=p.goal_metric WHERE n.value_per_100g IS NULL) THEN RAISE EXCEPTION 'Preset has incomplete data'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM colourfuel_web.product)<>3 OR (SELECT count(*) FROM colourfuel_web.goal_preset)<>6 THEN RAISE EXCEPTION 'Sample count mismatch'; END IF;
END $$;

DO $$ BEGIN
 IF (SELECT count(*) FROM colourfuel.recipe_ingredient WHERE recipe_id IN ('sample-rainbow-chicken','sample-vegan-power','sample-signature-salmon') AND version=1)<>18 THEN RAISE EXCEPTION 'Missing sample recipe ingredients'; END IF;
 IF (SELECT count(*) FROM colourfuel_web.recipes WHERE recipe_id IN ('sample-rainbow-chicken','sample-vegan-power','sample-signature-salmon'))<>3 THEN RAISE EXCEPTION 'Sample recipes failed source validation'; END IF;
END $$;

CREATE OR REPLACE VIEW colourfuel_web.catalog AS
SELECT jsonb_build_object(
 'ingredients',(SELECT coalesce(jsonb_agg(payload ORDER BY display_order),'[]'::jsonb) FROM colourfuel_web.ingredients),
 'recipes',(SELECT coalesce(jsonb_agg(payload ORDER BY display_order),'[]'::jsonb) FROM colourfuel_web.recipes),
 'metrics',(SELECT jsonb_agg(jsonb_build_object('metric_id',m.metric_id,'name_en',c.name_en,'unit',m.unit,'interpretation',m.interpretation) ORDER BY c.display_order) FROM colourfuel.nutrient_metric m JOIN colourfuel_web.metric_copy c USING(metric_id)),
 'datasets',(SELECT jsonb_agg(metadata ORDER BY dataset_id) FROM colourfuel_staging.dataset),
 'snapshot_date',(SELECT max(metadata->>'retrieved_on') FROM colourfuel_staging.dataset),
 'products',(SELECT jsonb_agg(to_jsonb(p) ORDER BY display_order) FROM colourfuel_web.product p),
 'presets',(SELECT jsonb_agg(to_jsonb(p) ORDER BY preset_id) FROM colourfuel_web.goal_preset p),
 'data_mode','live','read_at',statement_timestamp()
) AS payload;

INSERT INTO colourfuel.schema_migration VALUES ('005_sample_products',now(),'{"samples":3,"test_presets":6,"kitchen_validation":"pending","allergen_review":"pending"}') ON CONFLICT DO NOTHING;
